-- FINCELL Supabase backend
-- =========================
-- Run once in: Supabase Dashboard > SQL Editor > New query > paste > Run.
-- Creates the content table, storage bucket, RLS policies, and the baseline row.

-- 1) Content state - one JSONB row holds the whole site's content.
create table if not exists public.state (
  id integer primary key,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

alter table public.state enable row level security;

drop policy if exists "state public read" on public.state;
create policy "state public read" on public.state for select using (true);

drop policy if exists "state admin insert" on public.state;
create policy "state admin insert" on public.state for insert with check (auth.role() = 'authenticated');

drop policy if exists "state admin update" on public.state;
create policy "state admin update" on public.state for update using (auth.role() = 'authenticated');

-- 2) Media storage bucket - public read, authenticated upload/delete.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'media', 'media', true,
  10485760,
  array['image/png','image/jpeg','image/webp','image/gif']
)
on conflict (id) do nothing;

drop policy if exists "media public read" on storage.objects;
create policy "media public read" on storage.objects
  for select using (bucket_id = 'media');

drop policy if exists "media admin insert" on storage.objects;
create policy "media admin insert" on storage.objects
  for insert to authenticated with check (bucket_id = 'media');

drop policy if exists "media admin update" on storage.objects;
create policy "media admin update" on storage.objects
  for update to authenticated using (bucket_id = 'media');

drop policy if exists "media admin delete" on storage.objects;
create policy "media admin delete" on storage.objects
  for delete to authenticated using (bucket_id = 'media');

-- 3) Baseline content (only inserted if the row is absent).
